<?php require_once __DIR__ . '/../auth/guard.php'; requireRole('teacher'); ?>
<div class="admin-topbar"><div><h1>My Students' Progress</h1><p>Only students enrolled in your classes are shown. Review lesson progress and quiz logs.</p></div></div>
<div id="teacherProgressNotice" class="alert d-none" role="status"></div>
<div class="admin-card"><div class="admin-toolbar"><input id="teacherProgressSearch" class="admin-input" type="search" placeholder="Search student or class…" style="flex:1;min-width:220px"></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Student</th><th>Class / Section</th><th>Lessons</th><th>Quiz average</th><th>Attempts</th><th>Achievements</th><th>Last active</th><th></th></tr></thead><tbody id="teacherProgressRows"><tr><td colspan="8">Loading student progress…</td></tr></tbody></table></div></div>
<div class="admin-card mt-4" id="teacherStudentDetail" hidden><h2 class="h5 fw-bold" id="teacherDetailTitle">Student learning logs</h2><div class="row g-4"><div class="col-lg-6"><h3 class="h6 fw-bold">Lesson progress</h3><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Lesson</th><th>Category</th><th>Status</th><th>Progress</th><th>Last accessed</th></tr></thead><tbody id="teacherLessonLogs"></tbody></table></div></div><div class="col-lg-6"><h3 class="h6 fw-bold">Quiz attempts</h3><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Quiz</th><th>Score</th><th>Result</th><th>Date</th></tr></thead><tbody id="teacherQuizLogs"></tbody></table></div></div></div></div>
<script>
(function(){const ep='api/system_management.php',rows=document.getElementById('teacherProgressRows'),search=document.getElementById('teacherProgressSearch'),notice=document.getElementById('teacherProgressNotice'),detail=document.getElementById('teacherStudentDetail');if(!rows||rows.dataset.bound)return;rows.dataset.bound='1';let students=[];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function msg(t){notice.className='alert alert-danger';notice.textContent=t}
function render(){const term=search.value.toLowerCase();const data=students.filter(s=>[s.student_name,s.student_number,s.class_names].join(' ').toLowerCase().includes(term));rows.innerHTML=data.length?data.map(s=>{const total=Number(s.total_lessons)||0,done=Number(s.completed_lessons)||0,pct=total?Math.round(done/total*100):0;return '<tr><td><strong>'+esc(s.student_name)+'</strong><br><small>'+esc(s.student_number||'No student number')+'</small></td><td>'+esc(s.class_names||'Not assigned')+'</td><td>'+done+'/'+total+' ('+pct+'%)</td><td>'+(s.quiz_average===null?'—':esc(s.quiz_average)+'%')+'</td><td>'+Number(s.quiz_attempts)+'</td><td>'+Number(s.achievement_count)+'</td><td>'+esc(s.last_active||'No activity yet')+'</td><td><button class="admin-btn admin-btn-light" data-detail="'+s.student_id+'" data-name="'+esc(s.student_name)+'">View logs</button></td></tr>'}).join(''):'<tr><td colspan="8" class="text-center text-muted py-4">No students are assigned to your active classes yet.</td></tr>'}
async function load(){try{const r=await fetch(ep+'?view=progress',{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);students=d.students||[];render()}catch(e){msg(e.message);rows.innerHTML='<tr><td colspan="8">'+esc(e.message)+'</td></tr>'}}
rows.addEventListener('click',async e=>{const b=e.target.closest('[data-detail]');if(!b)return;try{const r=await fetch(ep+'?view=student_detail&student_id='+encodeURIComponent(b.dataset.detail),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message);document.getElementById('teacherDetailTitle').textContent='Learning logs: '+b.dataset.name;const pl=document.getElementById('teacherLessonLogs'),pq=document.getElementById('teacherQuizLogs');pl.innerHTML=d.lesson_logs.length?d.lesson_logs.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+esc(x.category_name)+'</td><td>'+esc(x.status)+'</td><td>'+Number(x.progress_percent)+'%</td><td>'+esc(x.last_accessed||'—')+'</td></tr>').join(''):'<tr><td colspan="5">No lesson activity yet.</td></tr>';pq.innerHTML=d.quiz_logs.length?d.quiz_logs.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+Number(x.score)+'/'+Number(x.total_items)+' ('+Number(x.percentage)+'%)</td><td>'+((Number(x.passed))?'Passed':'Not passed')+'</td><td>'+esc(x.completed_at||x.started_at)+'</td></tr>').join(''):'<tr><td colspan="4">No quiz attempts yet.</td></tr>';detail.hidden=false;detail.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){msg(err.message)}});search.addEventListener('input',render);load()})();
</script>